"""Self-contained Kaggle entrypoint for the isolated Beta v3 bootstrap."""

import base64
import io
import sys
import tarfile
from pathlib import Path


EMBEDDED_KRONOS_ARCHIVE_B64 = """

"""


source_root = Path("/kaggle/working/Kronos")
if not (source_root / "finetune/kaggle_v3_bootstrap_runner.py").is_file():
    archive = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64.strip())
    with tarfile.open(fileobj=io.BytesIO(archive), mode="r:gz") as bundle:
        bundle.extractall(source_root.parent)

sys.path.insert(0, str(source_root))
from finetune.kaggle_v3_bootstrap_runner import run


run(source_root)
